// LM Studio returns reasoning inline: drop <think> blocks so the chat shows only the answer.
let t = String($json.output || '');
t = t.replace(/<think>[\s\S]*?<\/think>/gi, '');
const close = t.lastIndexOf('</think>');
if (close !== -1) t = t.slice(close + '</think>'.length);
t = t.replace(/^\s*<think>/i, '').replace(/\*\*/g, '').trim();
return { json: { output: t || 'ARGUS could not produce an answer. Please rephrase the question.' } };
